import Dexie, { type Table } from 'dexie';
import type { IDriftInterpretationDB, IGlyphHistory, IRitualFrame, DriftCommentary, GameSaveData } from './types';

// Define the database
export class CodexDriftDB extends Dexie {
  interpretations!: Table<IDriftInterpretationDB, number>;
  glyphs!: Table<IGlyphHistory, string>;
  rituals!: Table<IRitualFrame, string>;
  driftCommentaries!: Table<DriftCommentary, number>;
  kvStore!: Table<{ key: string, value: any }, string>; // Generic Key-Value Store for App State
  gameSaves!: Table<GameSaveData, string>; // New table for robust slot saving

  constructor() {
    super('CodexDriftDatabase');

    // Version 1
    (this as Dexie).version(1).stores({
      interpretations: '++id, glyphId, glyphSymbol, timestamp, entropy, driftScore, ritualContext, version', 
      glyphs: '&id, symbol, lastInterpreted, driftVolatility', 
      rituals: '&id, timestamp, entropyLevel',
    });

    // Version 2: Added driftCommentaries table
    (this as Dexie).version(2).stores({
      interpretations: '++id, glyphId, glyphSymbol, timestamp, entropy, driftScore, ritualContext, version', 
      glyphs: '&id, symbol, lastInterpreted, driftVolatility',
      rituals: '&id, timestamp, entropyLevel',
      driftCommentaries: '++id, linkedDriftId, agent, timestamp',
    });

    // Version 3: Added kvStore for robust app state persistence (RPG saves, Profiles, etc.)
    (this as Dexie).version(3).stores({
      interpretations: '++id, glyphId, glyphSymbol, timestamp, entropy, driftScore, ritualContext, version', 
      glyphs: '&id, symbol, lastInterpreted, driftVolatility',
      rituals: '&id, timestamp, entropyLevel',
      driftCommentaries: '++id, linkedDriftId, agent, timestamp',
      kvStore: 'key', // Simple Key-Value store: key is primary key
    });

    // Version 4: Added gameSaves table for slots
    (this as Dexie).version(4).stores({
      interpretations: '++id, glyphId, glyphSymbol, timestamp, entropy, driftScore, ritualContext, version', 
      glyphs: '&id, symbol, lastInterpreted, driftVolatility',
      rituals: '&id, timestamp, entropyLevel',
      driftCommentaries: '++id, linkedDriftId, agent, timestamp',
      kvStore: 'key',
      gameSaves: 'slotId, timestamp', // slotId as primary key
    });

    (this as Dexie).open().catch(err => {
        console.error(`Failed to open Dexie database: ${err}`);
    });
  }

  async logDrift(interpretation: IDriftInterpretationDB): Promise<number | undefined> {
    if (!interpretation.glyphId || !interpretation.glyphSymbol) {
        console.error("logDrift: glyphId and glyphSymbol are required.", interpretation);
        return undefined;
    }
    try {
      return await (this as Dexie).transaction('rw', this.interpretations, this.glyphs, async () => {
        const interpretationId = await this.interpretations.add(interpretation);

        let glyph = await this.glyphs.get(interpretation.glyphId);
        if (!glyph) {
          glyph = {
            id: interpretation.glyphId,
            symbol: interpretation.glyphSymbol,
            entropyHistory: [interpretation.entropy],
            lastInterpreted: new Date(),
            driftVolatility: 0
          };
          await this.glyphs.add(glyph);
        } else {
          const newHistory = [...glyph.entropyHistory, interpretation.entropy].slice(-50); 
          const driftScores = await this.interpretations
            .where('glyphId').equals(interpretation.glyphId)
            .limit(50)
            .toArray()
            .then(items => items.map(i => i.driftScore));

          await this.glyphs.update(glyph.id, {
            entropyHistory: newHistory,
            lastInterpreted: new Date(),
            driftVolatility: this.calculateStdDev(driftScores)
          });
        }
        return interpretationId;
      });
    } catch (error) {
        console.error("Error in logDrift transaction:", error, "Interpretation:", interpretation);
        return undefined;
    }
  }

  private calculateStdDev(values: number[]): number {
    if (values.length < 2) return 0;
    const avg = values.reduce((a, b) => a + b, 0) / values.length;
    return Math.sqrt(
      values.map(v => Math.pow(v - avg, 2)).reduce((a, b) => a + b, 0) / values.length
    );
  }

  async getGlyphHistory(glyphNodeId: string): Promise<IDriftInterpretationDB[]> {
    return this.interpretations
      .where('glyphId')
      .equals(glyphNodeId)
      .sortBy('timestamp');
  }

  async addDriftCommentary(commentary: Omit<DriftCommentary, 'id'>): Promise<number> {
    return this.driftCommentaries.add(commentary as DriftCommentary);
  }

  async getCommentariesForDrift(driftId: number): Promise<DriftCommentary[]> {
    return this.driftCommentaries.where('linkedDriftId').equals(driftId).sortBy('timestamp');
  }

  // --- App State Persistence Methods ---

  async saveAppState(key: string, state: any): Promise<void> {
      await this.kvStore.put({ key, value: state });
  }

  async loadAppState(key: string): Promise<any | null> {
      const entry = await this.kvStore.get(key);
      return entry ? entry.value : null;
  }

  async clearAppState(key: string): Promise<void> {
      await this.kvStore.delete(key);
  }

  // --- Game Save Slot Methods ---

  async saveGameSlot(data: GameSaveData): Promise<void> {
      await this.gameSaves.put(data);
  }

  async loadGameSlot(slotId: string): Promise<GameSaveData | undefined> {
      return await this.gameSaves.get(slotId);
  }

  async getAllGameSaves(): Promise<GameSaveData[]> {
      return await this.gameSaves.toArray();
  }
}

export const driftDB = new CodexDriftDB();

import { useState, useCallback, useEffect, useRef } from 'react';
import type { PersistenceTarget, CodexStateSnapshot, GameSaveData, GameSaveSummary } from '../types';
import { driftDB } from '../db';

const APP_STATE_KEY = 'codex_full_state_v1';
const AUTO_SAVE_SLOT = 'autosave';
const AUTO_SAVE_INTERVAL = 60000; // 60 seconds

export const useCodexPersistence = (
  targets: PersistenceTarget[],
  currentStateValues: CodexStateSnapshot
) => {
  const [isHydrating, setIsHydrating] = useState(true);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [lastSavedTime, setLastSavedTime] = useState<number | null>(null);

  // Use a ref to hold current state for interval callbacks to avoid stale closures without frequent re-renders
  const stateRef = useRef(currentStateValues);

  useEffect(() => {
      stateRef.current = currentStateValues;
  }, [currentStateValues]);


  // --- Core Persistence Logic ---

  const saveGame = useCallback(async (slotId: string = 'manual_save') => {
    setSaveStatus('saving');
    try {
      const stateToSave: CodexStateSnapshot = {};

      // Copy targeted state properties
      if(stateRef.current) {
         targets.forEach(target => {
            switch(target) {
                case 'EchoLog': stateToSave.echoLog = stateRef.current.echoLog; break;
                case 'AgentGridState': stateToSave.agentGridState = stateRef.current.agentGridState; break;
                case 'GlyphTree': stateToSave.glyphTree = stateRef.current.glyphTree; break;
                case 'RitualState': stateToSave.ritualState = stateRef.current.ritualState; break;
                case 'SystemEntropy': stateToSave.systemEntropy = stateRef.current.systemEntropy; break;
                case 'AutoEchoState': stateToSave.autoEchoState = stateRef.current.autoEchoState; break;
                case 'EventHistory': stateToSave.eventHistory = stateRef.current.eventHistory; break;
                case 'ReweavingHistory': stateToSave.reweavingHistory = stateRef.current.reweavingHistory; break;
                case 'Artifacts': stateToSave.artifacts = stateRef.current.artifacts; break;
                case 'ActiveProfile': stateToSave.activeProfile = stateRef.current.activeProfile; break;
                case 'RPGState': stateToSave.rpgState = stateRef.current.rpgState; break;
            }
         });
      }

      // Construct Save Data Object
      const saveData: GameSaveData = {
          slotId,
          timestamp: Date.now(),
          previewData: {
              seekerName: stateRef.current.activeProfile?.name || 'Unknown Seeker',
              level: stateRef.current.activeProfile?.level || 1,
              location: stateRef.current.rpgState?.currentLocation || 'The Void',
              playtime: new Date().toLocaleTimeString(), // Simple placeholder
          },
          fullState: stateToSave
      };

      await driftDB.saveGameSlot(saveData);

      setLastSavedTime(Date.now());
      setSaveStatus('saved');

      // Revert status to idle after a moment
      setTimeout(() => setSaveStatus('idle'), 2000);

      console.log(`[CodexPersistence] Game saved to slot '${slotId}' at ${new Date().toLocaleTimeString()}`);
    } catch (e) {
      console.error("[CodexPersistence] Failed to save game:", e);
      setSaveStatus('error');
    }
  }, [targets]); // Dependency on targets is fine, state is via ref


  const loadGame = useCallback(async (slotId: string): Promise<CodexStateSnapshot | null> => {
    setIsHydrating(true);
    console.log(`[CodexPersistence] Loading game from slot '${slotId}'...`);

    try {
        const savedData = await driftDB.loadGameSlot(slotId);

        if (savedData && savedData.fullState) {
            setIsHydrating(false);
            return savedData.fullState;
        }

        // Fallback: Check kvStore (Legacy V3) if loading autosave
        if (slotId === AUTO_SAVE_SLOT) {
             const legacyState = await driftDB.loadAppState(APP_STATE_KEY);
             if (legacyState) {
                 console.log("[CodexPersistence] Legacy V3 state found, migrating...");
                 // Migrate to new format implicitly by returning it
                 return legacyState as CodexStateSnapshot;
             }
        }

        setIsHydrating(false);
        return null;

    } catch (e) {
        console.error("[CodexPersistence] Load failed:", e);
        setIsHydrating(false);
        return null;
    }
  }, []);

  const getSaveSlots = useCallback(async (): Promise<GameSaveSummary[]> => {
      try {
          const allSaves = await driftDB.getAllGameSaves();
          return allSaves.map(s => ({
              slotId: s.slotId,
              timestamp: s.timestamp,
              previewData: s.previewData
          })).sort((a,b) => b.timestamp - a.timestamp); // Newest first
      } catch (e) {
          console.error("Failed to fetch save slots", e);
          return [];
      }
  }, []);


  // --- Auto-Save Interval ---
  useEffect(() => {
    const intervalId = setInterval(() => {
        if (stateRef.current.activeProfile) { // Only auto-save if a profile exists
            saveGame(AUTO_SAVE_SLOT);
        }
    }, AUTO_SAVE_INTERVAL);

    return () => clearInterval(intervalId);
  }, [saveGame]);

  // --- Before Unload Save ---
  useEffect(() => {
      const handleBeforeUnload = () => {
          if (stateRef.current.activeProfile) {
             // This is a last-ditch effort, might not complete in all browsers
             // but strictly synchronous operations might block close. 
             // IndexedDB is async, so reliable "close-save" is hard.
             // We rely mostly on the interval, but trigger one here just in case logic allows.
             saveGame(AUTO_SAVE_SLOT); 
          }
      };
      window.addEventListener('beforeunload', handleBeforeUnload);
      return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [saveGame]);


  // --- Legacy Hydration (Initial Load) ---
  // This essentially acts as "Load Autosave" on boot
  const hydrateState = useCallback(async (): Promise<CodexStateSnapshot | null> => {
      return loadGame(AUTO_SAVE_SLOT);
  }, [loadGame]);


  // --- Export / Import Features (Keep as backup) ---
  const exportSave = useCallback(async () => {
    try {
        const saveData = await driftDB.loadGameSlot(AUTO_SAVE_SLOT);
        if (!saveData) {
            alert("No auto-save data found to export.");
            return;
        }

        const dataStr = JSON.stringify(saveData);
        const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
        const exportFileDefaultName = `TriSophian_Backup_${new Date().toISOString().slice(0,10)}.json`;

        const linkElement = document.createElement('a');
        linkElement.setAttribute('href', dataUri);
        linkElement.setAttribute('download', exportFileDefaultName);
        linkElement.click();
    } catch (e) {
        console.error("Export failed:", e);
    }
  }, []);

  const importSave = useCallback(async (file: File) => {
    return new Promise<boolean>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = async (event) => {
            try {
                if (event.target?.result && typeof event.target.result === 'string') {
                    const parsedData = JSON.parse(event.target.result) as GameSaveData;
                    // Basic validation
                    if (!parsedData.fullState || !parsedData.slotId) throw new Error("Invalid save file format.");

                    // Overwrite the imported slot ID to be 'manual_import' or keep original?
                    // Let's save it to a specific import slot to be safe
                    parsedData.slotId = 'imported_save'; 

                    await driftDB.saveGameSlot(parsedData);
                    console.log("[CodexPersistence] Imported save to 'imported_save' slot.");
                    resolve(true);
                }
            } catch (e) {
                console.error("Import failed:", e);
                reject(e);
            }
        };
        reader.readAsText(file);
    });
  }, []);


  return { 
    saveGame,
    loadGame,
    getSaveSlots,
    hydrateState, 
    isHydrating,
    saveStatus,
    lastSavedTime,
    exportSave,
    importSave
  };
};

import React, { useEffect, useState } from 'react';
import type { GameSaveSummary } from '../../types';
import { Button } from '../ui/Button';

interface SaveLoadModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (slotId: string) => Promise<void>;
  onLoad: (slotId: string) => Promise<void>;
  fetchSlots: () => Promise<GameSaveSummary[]>;
}

const SLOTS = ['slot_1', 'slot_2', 'slot_3'];

const SaveLoadModal: React.FC<SaveLoadModalProps> = ({ isOpen, onClose, onSave, onLoad, fetchSlots }) => {
  const [saves, setSaves] = useState<Record<string, GameSaveSummary>>({});
  const [isLoading, setIsLoading] = useState(false);
  const [autoSave, setAutoSave] = useState<GameSaveSummary | null>(null);

  const refreshSlots = async () => {
    setIsLoading(true);
    const data = await fetchSlots();
    const map: Record<string, GameSaveSummary> = {};
    let auto: GameSaveSummary | null = null;

    data.forEach(s => {
        if (s.slotId === 'autosave') auto = s;
        else map[s.slotId] = s;
    });
    setSaves(map);
    setAutoSave(auto);
    setIsLoading(false);
  };

  useEffect(() => {
    if (isOpen) refreshSlots();
  }, [isOpen]);

  if (!isOpen) return null;

  const SlotCard = ({ slotId, label, isAuto = false }: { slotId: string, label: string, isAuto?: boolean }) => {
    const save = isAuto ? autoSave : saves[slotId];
    const isEmpty = !save;

    return (
      <div className={`p-4 rounded-lg border ${isAuto ? 'border-amber-500/50 bg-amber-900/10' : 'border-indigo-500/50 bg-indigo-900/10'} flex flex-col gap-2 relative overflow-hidden group`}>
         <div className="flex justify-between items-center border-b border-white/10 pb-2 mb-1">
             <span className={`font-cinzel font-bold ${isAuto ? 'text-amber-400' : 'text-indigo-300'}`}>{label}</span>
             {save && <span className="text-[10px] text-slate-400 font-mono">{new Date(save.timestamp).toLocaleString()}</span>}
         </div>

         <div className="flex-grow min-h-[60px] flex flex-col justify-center">
            {isEmpty ? (
                <span className="text-slate-500 italic text-center text-sm">-- Empty Void --</span>
            ) : (
                <div className="text-xs text-slate-300 space-y-1">
                    <div className="font-bold text-white">{save.previewData.seekerName}</div>
                    <div className="flex justify-between">
                        <span>Level {save.previewData.level}</span>
                        <span>{save.previewData.location}</span>
                    </div>
                </div>
            )}
         </div>

         <div className="flex gap-2 mt-2">
            {!isAuto && (
                <button 
                    onClick={async () => { await onSave(slotId); refreshSlots(); }}
                    className="flex-1 bg-slate-700 hover:bg-slate-600 text-white text-xs py-1.5 rounded transition-colors border border-slate-500"
                >
                    <i className="ri-save-line mr-1"></i>Save
                </button>
            )}
            <button 
                onClick={async () => { 
                    if(!isEmpty) {
                        if(confirm("Load this reality? Unsaved progress will be lost.")) {
                            await onLoad(slotId); 
                            onClose();
                        }
                    }
                }}
                disabled={isEmpty}
                className={`flex-1 text-xs py-1.5 rounded transition-colors border ${isEmpty ? 'bg-slate-800 text-slate-600 border-slate-700 cursor-not-allowed' : 'bg-emerald-700 hover:bg-emerald-600 text-white border-emerald-500'}`}
            >
                <i className="ri-download-line mr-1"></i>Load
            </button>
         </div>

         {/* Holographic scanline effect */}
         <div className="absolute inset-0 pointer-events-none bg-gradient-to-b from-transparent via-white/5 to-transparent opacity-0 group-hover:opacity-20 transition-opacity duration-700 bg-[length:100%_4px]" style={{backgroundSize: '100% 4px'}}></div>
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[5000] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fade-in-up">
      <div className="absolute inset-0" onClick={onClose}></div>
      <div className="relative w-full max-w-4xl bg-slate-900 border-2 border-indigo-500/60 rounded-xl shadow-2xl flex flex-col overflow-hidden max-h-[90vh]">

        {/* Header */}
        <div className="p-4 bg-slate-950 border-b border-indigo-500/50 flex justify-between items-center">
            <h2 className="text-xl font-cinzel font-bold text-indigo-300 flex items-center gap-2">
                <i className="ri-archive-drawer-line"></i> Chronicle Vault
            </h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
                <i className="ri-close-line text-2xl"></i>
            </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto custom-scrollbar bg-slate-900/80">
            {isLoading ? (
                <div className="text-center py-20 text-indigo-400 animate-pulse">Syncing Timeline Archives...</div>
            ) : (
                <div className="space-y-6">
                    {/* Auto Save Section */}
                    <div className="mb-6">
                         <h4 className="text-xs font-mono text-slate-500 uppercase tracking-widest mb-2 border-b border-slate-800 pb-1">System Auto-Archive</h4>
                         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            <SlotCard slotId="autosave" label="Auto-Save (Latest)" isAuto={true} />
                         </div>
                    </div>

                    {/* Manual Slots */}
                    <div>
                        <h4 className="text-xs font-mono text-slate-500 uppercase tracking-widest mb-2 border-b border-slate-800 pb-1">Manual Stasis Pods</h4>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {SLOTS.map((slotId, i) => (
                                <SlotCard key={slotId} slotId={slotId} label={`Stasis Pod ${i+1}`} />
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* Footer */}
        <div className="p-3 bg-slate-950 border-t border-slate-800 text-center text-xs text-slate-500 italic">
            "Memory is the anchor of the soul." — Tablet of the Phoenix
        </div>
      </div>
    </div>
  );
};

