      {/* Replicated Menu items */}
      <div className="my-1 border-t border-slate-700"></div>
      <p className="px-4 pt-2 pb-1 text-xs text-slate-500 font-semibold uppercase">Flora</p>
      <button onClick={() => { onProvokeThornedRose(); closeAllMenus(); }} className="w-full text-left px-4 py-2 text-sm text-rose-300 hover:bg-slate-700 transition flex items-center"><i className="ri-spam-2-line mr-2"></i>Provoke Rose</button>
      <button onClick={() => { onTuneFrequency(); closeAllMenus(); }} className="w-full text-left px-4 py-2 text-sm text-sky-300 hover:bg-slate-700 transition flex items-center"><i className="ri-signal-tower-line mr-2"></i>Tune Lily</button>

       <div className="my-1 border-t border-slate-700"></div>
      <p className="px-4 pt-2 pb-1 text-xs text-slate-500 font-semibold uppercase">Oracle</p>
      <button onClick={() => { onInvokeGeminiOracle(); closeAllMenus(); }} className="w-full text-left px-4 py-2 text-sm text-fuchsia-300 hover:bg-slate-700 transition flex items-center"><i className="ri-sparkling-2-line mr-2"></i>Invoke Gemini Oracle</button>
      <button onClick={() => { onContextualOracleQuery(); closeAllMenus(); }} className="w-full text-left px-4 py-2 text-sm text-teal-300 hover:bg-slate-700 transition flex items-center"><i className="ri-compass-3-line mr-2"></i>Contextual Oracle Query</button>
       <div className="my-1 border-t border-slate-700"></div>
