      {onExportSave && (
        <button onClick={() => { onExportSave(); closeAllMenus(); }} className="w-full text-left px-4 py-2 text-sm text-cyan-300 hover:bg-slate-700 transition flex items-center">
            <i className="ri-download-cloud-line mr-2"></i>Export Save
        </button>
