import React, { createContext, useState, useCallback, useContext, ReactNode } from 'react';
import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai"; 
import type { GeminiContextType } from '../types';

const GeminiContext = createContext<GeminiContextType | undefined>(undefined);

export const GeminiProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastGeminiResponseText, setLastGeminiResponseText] = useState<string | null>(null);

  // Helper to get a fresh client instance with the current API key.
  const getAiClient = useCallback(() => {
    const key = process.env.API_KEY;
    if (!key) {
        console.error("Gemini API Key is missing.");
        return null;
    }
    try {
      return new GoogleGenAI({ apiKey: key });
    } catch (e) {
      console.error("Error creating GoogleGenAI client:", e);
      return null;
    }
  }, []);

  const invokeGemini = useCallback(async (prompt: string, systemInstruction?: string, responseMimeType?: "text/plain" | "application/json"): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) {
      const noClientError = new Error("Gemini API client not initialized. API Key might be missing or invalid.");
      setError(noClientError);
      return null;
    }

    setIsGenerating(true);
    setError(null);
    setLastGeminiResponseText(null);

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash', 
        contents: prompt,
        ...(systemInstruction && { config: { systemInstruction, ...(responseMimeType && {responseMimeType}) } }),
        ...(!systemInstruction && responseMimeType && { config: { responseMimeType } }),
      });

      const text = response.text; 
      setLastGeminiResponseText(text);
      setIsGenerating(false);
      return text;
    } catch (e) {
      const err = e instanceof Error ? e : new Error('An unknown error occurred while calling Gemini API');
      console.error("Error invoking Gemini API (text):", err);
      setError(err);
      setIsGenerating(false);
      return null;
    }
  }, [getAiClient]);

  const generateImage = useCallback(async (prompt: string, model: 'imagen-4.0-generate-001' | 'gemini-2.5-flash-image' = 'imagen-4.0-generate-001'): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) {
      const noClientError = new Error("Gemini API client for images not initialized. API Key might be missing or invalid.");
      setError(noClientError);
      return null;
    }

    setIsGenerating(true);
    setError(null);

    try {
      if (model === 'gemini-2.5-flash-image') {
         const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: prompt }]
            },
            config: {}
         });

         if (response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData) {
                    const base64EncodeString: string = part.inlineData.data;
                    const mimeType = part.inlineData.mimeType || 'image/png';
                    const imageUrl = `data:${mimeType};base64,${base64EncodeString}`;
                    setIsGenerating(false);
                    return imageUrl;
                }
            }
         }
         console.warn("No image part returned from gemini-2.5-flash-image. Falling back to null.");
         setIsGenerating(false);
         return null;

      } else {
          const response = await ai.models.generateImages({
            model: model,
            prompt: prompt,
            config: { numberOfImages: 1, outputMimeType: 'image/png' },
          });

          if (response.generatedImages && response.generatedImages.length > 0 && response.generatedImages[0].image?.imageBytes) {
            const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
            const imageUrl = `data:image/png;base64,${base64ImageBytes}`;
            setIsGenerating(false);
            return imageUrl;
          } else {
            throw new Error('No image data received from API.');
          }
      }
    } catch (e) {
      const err = e instanceof Error ? e : new Error('An unknown error occurred while calling Gemini Image API');
      console.error("Error invoking Gemini API (image):", err);
      setError(err);
      setIsGenerating(false);
      return null;
    }
  }, [getAiClient]);

  const generateVideo = useCallback(async (prompt: string, imageBase64?: string): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) {
        const noClientError = new Error("Gemini API client not initialized. API Key might be missing.");
        setError(noClientError);
        return null;
    }

    setIsGenerating(true);
    setError(null);

    try {
        let operation;
        if (imageBase64) {
             const base64Data = imageBase64.split(',')[1] || imageBase64;
             operation = await ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: prompt, 
                image: {
                    imageBytes: base64Data,
                    mimeType: 'image/png', 
                },
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
             });
        } else {
            operation = await ai.models.generateVideos({
                model: 'veo-3.1-fast-generate-preview',
                prompt: prompt,
                config: {
                    numberOfVideos: 1,
                    resolution: '720p',
                    aspectRatio: '16:9'
                }
            });
        }

        while (!operation.done) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            operation = await ai.operations.getVideosOperation({operation: operation});
        }

        const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;

        if (videoUri) {
            // Fetch using the current key
            const key = process.env.API_KEY;
            const fetchUrl = `${videoUri}&key=${key}`;
            const videoResponse = await fetch(fetchUrl);
            const videoBlob = await videoResponse.blob();
            const videoUrl = URL.createObjectURL(videoBlob);

            setIsGenerating(false);
            return videoUrl;
        } else {
            throw new Error("Video generation completed but no URI returned.");
        }

    } catch (e: any) {
        const err = e instanceof Error ? e : new Error(JSON.stringify(e));
        console.error("Error invoking Gemini API (video):", err);

        if (err.message.includes("404") || err.message.includes("Requested entity was not found")) {
             console.warn("Veo model 404 error detected. Prompting for API key selection...");
             if (typeof window !== 'undefined' && (window as any).aistudio) {
                 try {
                     await (window as any).aistudio.openSelectKey();
                 } catch (keyErr) {
                     console.error("Failed to open key selection dialog:", keyErr);
                 }
             }
        }

        setError(err);
        setIsGenerating(false);
        return null;
    }
  }, [getAiClient]);

  const generateSpeech = useCallback(async (text: string, voiceName: string = 'Kore'): Promise<ArrayBuffer | null> => {
    const ai = getAiClient();
    if (!ai) {
      console.error("Gemini API client not initialized for speech.");
      return null;
    }

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const binaryString = atob(base64Audio);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes.buffer;
      }
      return null;
    } catch (e) {
      console.error("Error generating speech:", e);
      return null;
    }
  }, [getAiClient]);

  return (
    <GeminiContext.Provider value={{ isGenerating, error, lastGeminiResponseText, invokeGemini, generateImage, generateVideo, generateSpeech }}>
      {children}
    </GeminiContext.Provider>
  );
};

export const useGemini = (): GeminiContextType => {
  const context = useContext(GeminiContext);
  if (context === undefined) {
    throw new Error('useGemini must be used within a GeminiProvider');
  }
  return context;
};

export interface QuestFrame {
  image: HTMLImageElement;
  text: string;
  durationMs: number;
  audioBuffer?: AudioBuffer | null;
}

export class QuestCinemaEngine {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private mediaRecorder: MediaRecorder | null = null;
  private recordedChunks: Blob[] = [];
  private width: number = 1280;
  private height: number = 720;
  private fps: number = 30;
  private audioCtx: AudioContext;
  private destNode: MediaStreamAudioDestinationNode;

  constructor() {
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.width;
    this.canvas.height = this.height;
    this.ctx = this.canvas.getContext('2d')!;

    // Initialize Audio Context for mixing
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    this.audioCtx = new AudioContextClass();
    this.destNode = this.audioCtx.createMediaStreamDestination();
  }

  private async loadImage(src: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => resolve(img);
      img.onerror = (e) => reject(e);
      img.src = src;
    });
  }

  // Wraps text for subtitles
  private wrapText(text: string, maxWidth: number): string[] {
    const words = text.split(' ');
    const lines = [];
    let currentLine = words[0];

    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        const width = this.ctx.measureText(currentLine + " " + word).width;
        if (width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
  }

  public async compileVideo(
    slides: { imageUrl: string; text: string }[],
    onProgress: (progress: number) => void,
    audioGenerator?: (text: string) => Promise<ArrayBuffer | null>
  ): Promise<Blob> {
    this.recordedChunks = [];
    if (this.audioCtx.state === 'suspended') {
        await this.audioCtx.resume();
    }

    // 1. Preload Assets (Images & Audio)
    const frames: QuestFrame[] = [];
    const defaultDuration = 5000;

    for (let i = 0; i < slides.length; i++) {
      try {
        const img = await this.loadImage(slides[i].imageUrl);
        let audioBuffer: AudioBuffer | null = null;
        let durationMs = defaultDuration;

        if (audioGenerator) {
            try {
                // Shorten text for TTS to avoid extremely long generation times
                const ttsText = slides[i].text.length > 200 ? slides[i].text.substring(0, 200) + "..." : slides[i].text;
                const audioData = await audioGenerator(ttsText);
                if (audioData) {
                    audioBuffer = await this.audioCtx.decodeAudioData(audioData);
                    // Adjust slide duration to match audio if audio is longer than default
                    // Add 1s padding
                    durationMs = Math.max(defaultDuration, (audioBuffer.duration * 1000) + 1000);
                }
            } catch (audioErr) {
                console.warn("Failed to generate/decode audio for slide", i, audioErr);
            }
        }

        frames.push({
          image: img,
          text: slides[i].text,
          durationMs: durationMs,
          audioBuffer: audioBuffer
        });
      } catch (e) {
        console.warn("Failed to load image for video frame", i);
      }
      onProgress(0.1 + (i / slides.length) * 0.3); // First 40% is loading
    }

    if (frames.length === 0) throw new Error("No valid frames to compile.");

    // 2. Setup Recorder with Mixed Stream (Video + Audio)
    const canvasStream = this.canvas.captureStream(this.fps);
    const combinedTracks = [
        ...canvasStream.getVideoTracks(),
        ...this.destNode.stream.getAudioTracks()
    ];
    const combinedStream = new MediaStream(combinedTracks);

    // Use standard supported mime types
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus') 
        ? 'video/webm;codecs=vp9,opus' 
        : 'video/webm';

    this.mediaRecorder = new MediaRecorder(combinedStream, { mimeType, videoBitsPerSecond: 5000000 });

    this.mediaRecorder.ondataavailable = (event) => {
      if (event.data.size > 0) this.recordedChunks.push(event.data);
    };

    const recordingPromise = new Promise<Blob>((resolve) => {
      this.mediaRecorder!.onstop = () => {
        const blob = new Blob(this.recordedChunks, { type: mimeType });
        resolve(blob);
      };
    });

    this.mediaRecorder.start();

    // 3. Render Loop
    let currentFrameIdx = 0;
    let currentSlideStartTime = performance.now();
    let audioSourceNode: AudioBufferSourceNode | null = null;
    let slideAudioStarted = false;

    // Calculate total duration for progress
    const totalDurationMs = frames.reduce((acc, f) => acc + f.durationMs, 0);
    let accumulatedTimeMs = 0;

    return new Promise((resolve) => {
        let startTime = performance.now();

        const loop = (now: number) => {
            const globalDelta = now - startTime;
            const slideDelta = now - currentSlideStartTime;

            // Progress Calculation
            const percentComplete = Math.min(0.99, 0.4 + (globalDelta / totalDurationMs) * 0.6);
            onProgress(percentComplete);

            const frame = frames[currentFrameIdx];

            // --- AUDIO TRIGGER ---
            if (frame && !slideAudioStarted) {
                if (frame.audioBuffer) {
                    audioSourceNode = this.audioCtx.createBufferSource();
                    audioSourceNode.buffer = frame.audioBuffer;
                    audioSourceNode.connect(this.destNode);
                    audioSourceNode.start();
                } else {
                    // Create a silent filler or ambient drone here if needed
                    // For now, silence is fine, the video track continues
                }
                slideAudioStarted = true;
            }

            // --- DRAWING LOGIC ---
            this.ctx.fillStyle = '#000';
            this.ctx.fillRect(0, 0, this.width, this.height);

            if (frame) {
                // Ken Burns Effect (Pan/Zoom)
                const progress = Math.min(1, slideDelta / frame.durationMs);
                const zoom = 1 + progress * 0.1; // 1.0 to 1.1
                // Alternate pan direction based on index
                const panX = currentFrameIdx % 2 === 0 
                    ? -progress * 50 
                    : -50 + progress * 50;

                this.ctx.save();
                // Clip to canvas
                this.ctx.beginPath();
                this.ctx.rect(0, 0, this.width, this.height);
                this.ctx.clip();

                // Draw Image
                this.ctx.translate(this.width/2, this.height/2);
                this.ctx.scale(zoom, zoom);
                this.ctx.translate(-this.width/2 + panX, -this.height/2);

                // Draw image 'cover' style
                const scale = Math.max(this.width / frame.image.width, this.height / frame.image.height);
                const x = (this.width / 2) - (frame.image.width / 2) * scale;
                const y = (this.height / 2) - (frame.image.height / 2) * scale;
                this.ctx.drawImage(frame.image, x, y, frame.image.width * scale, frame.image.height * scale);

                this.ctx.restore();

                // Cinematic Letterbox
                this.ctx.fillStyle = '#000';
                this.ctx.fillRect(0, 0, this.width, 60); // Top bar
                this.ctx.fillRect(0, this.height - 120, this.width, 120); // Bottom bar

                // Text Overlay
                this.ctx.font = '24px "Cinzel", serif';
                this.ctx.fillStyle = '#fbbf24'; // Amber
                this.ctx.textAlign = 'center';
                this.ctx.shadowColor = 'black';
                this.ctx.shadowBlur = 4;

                const lines = this.wrapText(frame.text, this.width - 100);
                // Fade in text
                const textAlpha = Math.min(1, slideDelta / 1000); 
                this.ctx.globalAlpha = textAlpha;

                lines.forEach((line, i) => {
                    // Limit lines to fit in bottom bar
                    if(i < 3) { 
                        this.ctx.fillText(line, this.width / 2, this.height - 80 + (i * 30));
                    }
                });
                this.ctx.globalAlpha = 1;
            }

            // Check if slide finished
            if (slideDelta >= frame.durationMs) {
                // Stop current audio if still playing (though duration should match)
                if (audioSourceNode) {
                    try { audioSourceNode.stop(); } catch(e) {}
                    audioSourceNode.disconnect();
                    audioSourceNode = null;
                }

                accumulatedTimeMs += frame.durationMs;
                currentFrameIdx++;
                currentSlideStartTime = now;
                slideAudioStarted = false; // Reset for next slide

                if (currentFrameIdx >= frames.length) {
                    this.mediaRecorder?.stop();
                    resolve(recordingPromise);
                    return;
                }
            }

            requestAnimationFrame(loop);
        };
        requestAnimationFrame(loop);
    });
  }
}

