            </div>
        )}
      </div>

      <div className="flex-grow overflow-hidden flex flex-col relative">
        {activeTab === 'profile' && (
            <div className="p-6 overflow-y-auto custom-scrollbar space-y-6">

                {/* TCG CARD DISPLAY AREA */}
                <div className="flex flex-col md:flex-row gap-6 items-center md:items-start">
                    {/* The Rendered Card */}
                    <div className="w-64 flex-shrink-0 relative group">
                         <TCGCard 
                            id="seeker-tcg-card"
                            name={name || "Unknown Seeker"}
                            type={`${race} ${seekerClass}`}
                            rarity={ArtifactRarity.Legendary}
                            imageUrl={avatarUrl}
                            description={`A ${alignment} ${race} wandering the Codex. ${existingProfile?.selfTraits.join(', ') || ''}`}
                            stats={seekerStats}
                            auraColor={aura}
                            isZoomed
                         />
                         <div className="mt-3 flex gap-2 justify-center">
                            <Button onClick={handleGenerateAvatar} disabled={isGeneratingAvatar} className="text-xs py-1.5 px-3 bg-indigo-700 hover:bg-indigo-600 w-full">
                                {isGeneratingAvatar ? <i className="ri-loader-4-line animate-spin"></i> : <i className="ri-magic-line mr-1"></i>} 
                                Generate Art
                            </Button>
                             <Button onClick={handleDownloadCard} disabled={!avatarUrl} className="text-xs py-1.5 px-3 bg-slate-700 hover:bg-slate-600 w-full">
                                <i className="ri-download-line mr-1"></i> Save Card
