                                    >
                                        {ALL_GENDERS_LIST.map(g => <option key={g} value={g}>{g}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs text-slate-400 font-bold uppercase">Alignment</label>
