                                    >
                                        {ALL_ALIGNMENTS_LIST.map(a => <option key={a} value={a}>{a}</option>)}
                                    </select>
                                </div>
                            </div>

                             <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-xs text-slate-400 font-bold uppercase">Reality Filter</label>
                                     <select 
                                        value={visualFilter} 
                                        onChange={e => setVisualFilter(e.target.value as SeekerVisualFilter)}
                                        className="w-full bg-slate-800 border border-slate-700 rounded p-2 text-slate-100 focus:border-indigo-500 outline-none"
                                    >
                                        {SEEKER_VISUAL_FILTERS.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                                    </select>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs text-slate-400 font-bold uppercase mb-1">Aura Signature</label>
