      if (onSaveState && gameMode === 'PLAYING') {
        const stateToSave = {
            currentLocation: location as RPGGameLocation, 
            narrativeHistory: narrativeLog,
            activeQuests: activeQuests, 
            lastActionTimestamp: Date.now(),
            currentSceneDescription: sceneDescription,
            currentSceneImageUrl: sceneImageUrl,
            availableActions: availableActions,
            achievements: unlockedAchievements,
            vitals: { integrity, sanity }
        };
        const timer = setTimeout(() => onSaveState(stateToSave), 1000);
        return () => clearTimeout(timer);
      }
  }, [location, narrativeLog, sceneDescription, sceneImageUrl, availableActions, activeQuests, unlockedAchievements, gameMode, integrity, sanity, onSaveState]);


  useEffect(() => {
    if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [narrativeLog]);

  useEffect(() => {
      if (achievementToast) {
          const timer = setTimeout(() => setAchievementToast(null), 4000);
          return () => clearTimeout(timer);
      }
  }, [achievementToast]);

  useEffect(() => {
      if (levelUpToast) {
          const timer = setTimeout(() => setLevelUpToast(null), 5000);
          return () => clearTimeout(timer);
      }
  }, [levelUpToast]);

  const constructCharacterContext = (profile: any) => {
      if (!profile) return "Unknown Entity";
      let context = `${profile.name}, a ${profile.gender} ${profile.race} ${profile.class}.`;

      const equipment = [];
      if (profile.equippedWeapon) equipment.push(`Wielding: ${profile.equippedWeapon.name} (${profile.equippedWeapon.description})`);
      if (profile.equippedOutfit) equipment.push(`Wearing: ${profile.equippedOutfit.name} (${profile.equippedOutfit.description})`);
      if (profile.equippedCompanion) equipment.push(`Accompanied by: ${profile.equippedCompanion.name} (${profile.equippedCompanion.description})`);
      if (profile.equippedRelic) equipment.push(`Holding Relic: ${profile.equippedRelic.name}`);

      if (equipment.length > 0) context += " Equipment: " + equipment.join(". ") + ".";
      if (profile.auraColor) context += ` Aura: ${profile.auraColor}.`;
      if (profile.selfTraits && profile.selfTraits.length > 0) context += ` Traits: ${profile.selfTraits.join(', ')}.`;
      return context;
  };

  const getInventoryContext = (profile: any) => {
      if (!profile || !profile.inventory) return "Empty";
      return profile.inventory.map((i: any) => i.name).join(", ");
  };

  const generateDynamicLocations = async () => {
      if(isGeneratingLocations) return;
      setIsGeneratingLocations(true);
      setGeneratedLocations({}); 
      setGeneratedQuests([]); 
      setSelectedStartLoc(null);

      const prompt = `
        Generate 3 unique, evocative RPG locations for a sci-fi/fantasy setting heavily influenced by entropy level ${currentEntropy.toFixed(2)}.
        The setting involves ancient codices, glitching reality, and cosmic horror.
        Respond with a JSON object where keys are location names and values are objects with fields:
        - "description": Short evocative description.
        - "risk": "Low", "Medium", "High", or "Extreme".
        - "color": A tailwind text color class (e.g. "text-red-400").
        - "icon": A RemixIcon class name (e.g. "ri-skull-line").
      `;

      try {
        const response = await invokeGemini(prompt, "You are a creative world-building AI. Respond ONLY in valid JSON.");
        if (response) {
            const jsonStr = response.replace(/```json/g, '').replace(/```/g, '').trim();
            const locs = JSON.parse(jsonStr);
            setGeneratedLocations(locs);
        } else {
             setGeneratedLocations(FALLBACK_LOCATIONS);
        }
      } catch (e) {
          console.error("Location Gen Error", e);
          setGeneratedLocations(FALLBACK_LOCATIONS);
      } finally {
          setIsGeneratingLocations(false);
      }
  };

  const generateDynamicQuests = async (locationName: string) => {
      if(isGeneratingQuests || !locationName) return;
      setIsGeneratingQuests(true);
      setGeneratedQuests([]);
      setSelectedQuestTemplate(null);

      const locDesc = generatedLocations[locationName]?.description || "A mysterious place.";
      const prompt = `
        Generate 3 RPG quest hooks for the location "${locationName}" (${locDesc}).
        The player is a ${activeProfile?.race} ${activeProfile?.class}.
        Theme: Entropy ${currentEntropy.toFixed(2)}, Cosmic Mystery.
        Respond with a JSON array of objects with fields:
        - "id": unique string id
        - "title": Quest title
        - "desc": Short objective description
        - "difficulty": "Normal", "Hard", or "Extreme"
      `;

      try {
        const response = await invokeGemini(prompt, "You are a creative quest designer AI. Respond ONLY in valid JSON.");
        if (response) {
             const jsonStr = response.replace(/```json/g, '').replace(/```/g, '').trim();
             const quests = JSON.parse(jsonStr);
             setGeneratedQuests(quests);
        }
      } catch (e) {
          console.error("Quest Gen Error", e);
          setGeneratedQuests([
              { id: 'q_fallback_1', title: 'Survey the Area', desc: 'Map out the immediate surroundings.', difficulty: 'Normal' },
              { id: 'q_fallback_2', title: 'Find the Source', desc: 'Locate the source of local disturbance.', difficulty: 'Hard' }
          ]);
      } finally {
          setIsGeneratingQuests(false);
      }
  };

  const handleLocationSelect = (locName: string) => {
      setSelectedStartLoc(locName);
      generateDynamicQuests(locName);
  };

  const visualHistory = useMemo(() => {
      return artifacts
          .filter(a => a.type === ArtifactType.VisualMemory)
          .sort((a, b) => b.timestamp - a.timestamp) 
          .map(a => ({
              id: a.id,
              url: a.imageUrl || '',
              loc: a.metaData?.location || 'Unknown',
              desc: a.description,
              timestamp: a.timestamp
          }));
  }, [artifacts]);

  useEffect(() => {
    if (!activeProfile || isProcessing || criticalState || gameMode !== 'PLAYING') return;

    const triggerAmbientEvent = () => {
        const chance = 0.3 + (currentEntropy * 0.5); 
        if (Math.random() < chance) {
            const ambientEventsLow = ["A distant chime resonates.", "The light dims momentarily.", "Dust motes swirl.", "Calm observation."];
            const ambientEventsHigh = ["The walls breathe.", "A whisper backwards.", "Geometric fractals bleed.", "Gravity shifts.", "A memory not yours."];
            const pool = currentEntropy > 0.6 ? ambientEventsHigh : ambientEventsLow;
            addToLog(pool[Math.floor(Math.random() * pool.length)], 'ambient');
        }
    };
    const delay = (20000 + Math.random() * 20000) * (1 - currentEntropy * 0.5);
    ambientTimerRef.current = window.setTimeout(triggerAmbientEvent, delay);
    return () => { if (ambientTimerRef.current) clearTimeout(ambientTimerRef.current); };
  }, [narrativeLog, currentEntropy, isProcessing, activeProfile, criticalState, gameMode]);


  const addToLog = (text: string, type: 'narration' | 'action' | 'system' | 'ambient' = 'narration') => {
    setNarrativeLog(prev => [...prev, { text, type, timestamp: Date.now() }]);
  };

  const speakNarrative = async (text: string) => {
      // Use high quality Gemini TTS if available
      try {
        const arrayBuffer = await generateSpeech(text, 'Kore');
        if (arrayBuffer) {
           const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
           const audioBufferSource = audioCtx.createBufferSource();
           audioBufferSource.buffer = await audioCtx.decodeAudioData(arrayBuffer);
           audioBufferSource.connect(audioCtx.destination);
           audioBufferSource.start();
           return;
        }
      } catch (e) {
          console.warn("Gemini TTS failed, falling back to WebSpeech", e);
      }

      // Fallback to WebSpeech
      const profile = voiceProfiles.find(p => p.id === activeVoiceId) || voiceProfiles.find(p => p.agent === AgentName.RPGNexusAgent) || voiceProfiles.find(p => p.agent === 'SystemDebug');
      if (profile) voiceEngine.speak(text, profile).catch(e => console.warn("Voice Error", e));
  };

  const handlePlayAudio = () => {
      const textToSpeak = sceneDescription || (narrativeLog.length > 0 ? narrativeLog[narrativeLog.length - 1].text : "");
      if (textToSpeak) {
          speakNarrative(textToSpeak);
          addEchoMessage(AgentName.RPGNexusAgent, "Narrative audio stream active.", "text-indigo-400");
      }
  };

  const handleGenerateVideo = async () => {
      if (isVideoGenerating || !sceneImageUrl) return;
      setIsVideoGenerating(true);
      addEchoMessage(AgentName.RPGNexusAgent, "Manifesting scene into motion...", "text-fuchsia-400");
      try {
          const videoUrl = await generateVideo(sceneDescription, sceneImageUrl);
          if (videoUrl) {
              setSceneVideoUrl(videoUrl);
              addEchoMessage(AgentName.RPGNexusAgent, "Motion manifestation complete.", "text-emerald-400");
          } else {
              addEchoMessage(AgentName.RPGNexusAgent, "Motion synthesis failed.", "text-rose-400");
          }
      } catch (error) {
          console.error("Video Gen Error", error);
          addEchoMessage(AgentName.RPGNexusAgent, "Video generation error.", "text-rose-400");
      } finally {
          setIsVideoGenerating(false);
      }
  };

  const handleCompileQuestVideo = async () => {
      if (isVideoCompiling || visualHistory.length === 0) return;

      setIsVideoCompiling(true);
      setCompilationProgress(0);
      addEchoMessage(AgentName.RPGNexusAgent, "Compiling visual chronicle into cinema reel...", "text-purple-300");

      try {
        const composer = new QuestCinemaEngine();
        const slides = visualHistory.map(v => ({
            imageUrl: v.url,
            text: v.desc || `Scene from ${v.loc}`
        }));

        // Add current scene if not in history yet
        if (sceneImageUrl) {
            slides.push({ imageUrl: sceneImageUrl, text: sceneDescription });
        }

        // Reverse to show oldest first for chronological order
        slides.reverse();

        // Pass the speech generator to the engine
        const audioGenerator = async (text: string) => {
            return await generateSpeech(text, 'Kore');
        };

        const blob = await composer.compileVideo(slides, (progress) => {
            setCompilationProgress(Math.floor(progress * 100));
        }, audioGenerator);

        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Codex_Quest_Reel_${Date.now()}.webm`;
        a.click();

        addEchoMessage(AgentName.RPGNexusAgent, "Quest Reel materialized.", "text-emerald-400");

      } catch (e) {
          console.error("Video Compilation Error", e);
          addEchoMessage(AgentName.System, "Failed to compile quest video.", "text-rose-400");
      } finally {
          setIsVideoCompiling(false);
          setCompilationProgress(0);
      }
  };

  const generateSceneVisuals = async (locationName: string, context: string) => {
      if (isImageGenerating) return;
      setIsImageGenerating(true);

      // Enriched Visual Prompt
      const charContext = constructCharacterContext(activeProfile);
      // Simplify context for prompt to avoid token limits or confusion, keeping key visuals
      const visualProps = `Character: ${activeProfile?.race} ${activeProfile?.class}, ${activeProfile?.gender}. Wearing: ${activeProfile?.equippedOutfit?.name || 'Standard Gear'}. Wielding: ${activeProfile?.equippedWeapon?.name || 'Weapon'}. Aura: ${activeProfile?.auraColor}.`;

      const prompt = `Fantasy Sci-Fi RPG Scene: ${locationName}. ${context}. 
      Visual Details: ${visualProps}
      Style: ${activeProfile?.visualFilter || 'Cyberpunk'}, detailed, atmospheric, entropy level ${currentEntropy.toFixed(2)}.`;

      try {
          const url = await generateImage(prompt, 'imagen-4.0-generate-001'); // or gemini-2.5-flash-image
          if (url) {
              setSceneImageUrl(url);
              if (onArtifactCreated) {
                  const artifact: CodexArtifact = {
                      id: `visual-${Date.now()}`,
                      name: `Visual: ${locationName}`,
                      type: ArtifactType.VisualMemory,
                      rarity: ArtifactRarity.Common,
                      description: context,
                      imageUrl: url,
                      timestamp: Date.now(),
                      metaData: { location: locationName, characterContext: visualProps }
                  };
                  onArtifactCreated(artifact);
              }
          }
      } catch (e) {
          console.error("Visual Gen Error", e);
      } finally {
          setIsImageGenerating(false);
      }
  };

  const handleAction = async (actionLabel: string, type: 'action', risk: number) => {
      if (isProcessing || criticalState) return;
      setIsProcessing(true);
      addToLog(actionLabel, 'action');

      const charContext = constructCharacterContext(activeProfile);

      const systemInstruction = `You are the Game Master (Nexus Agent) for a text-based RPG set in the Tri-Sophian Codex universe. 
      Current Entropy: ${currentEntropy}. 
      Player Full Profile: ${charContext}
      Inventory: ${getInventoryContext(activeProfile)}
      Location: ${location}.
      Current Quest: ${activeQuests[0]?.title || 'None'}.

      Respond with a JSON object containing:
      - "narrative": The outcome description (2-3 sentences). Ensure it reflects the character's race, class, and specifically their equipped items if relevant to the action.
      - "integrityDelta": Integer change to HP (negative for damage).
      - "sanityDelta": Integer change to Sanity (negative for trauma).
      - "newActions": Array of 2-3 dynamic actions (objects with "id", "label", "type"="action", "risk" integer).
      - "loot": Optional. Object with "name", "type", "rarity" if an item is found.
      `;

      const prompt = `Player performs: "${actionLabel}". Risk Level: ${risk}. Determine the outcome based on entropy, stats, and equipment.`;

      try {
          const response = await invokeGemini(prompt, systemInstruction);
          if (response) {
             const cleanJson = response.replace(/```json/g, '').replace(/```/g, '').trim();
             try {
                const result = JSON.parse(cleanJson);

                // Update Narrative
                addToLog(result.narrative, 'narration');
                setSceneDescription(result.narrative);
                speakNarrative(result.narrative);

                // Update Vitals
                const newIntegrity = Math.max(0, Math.min(100, integrity + (result.integrityDelta || 0)));
                const newSanity = Math.max(0, Math.min(100, sanity + (result.sanityDelta || 0)));
                setIntegrity(newIntegrity);
                setSanity(newSanity);

                // Check Critical States
                if (newIntegrity <= 0) setCriticalState('death');
                if (newSanity <= 0) setCriticalState('madness');

                // Update Actions
                if (result.newActions && Array.isArray(result.newActions)) {
                    setAvailableActions(result.newActions.map((a: any) => ({ ...a, isDynamic: true })));
                }

                // Handle Loot
                if (result.loot) {
                    const newItem: MarketItem = {
                        id: `loot-${Date.now()}`,
                        name: result.loot.name,
                        type: result.loot.type || 'Relic',
                        rarity: result.loot.rarity || 'Common',
                        description: 'Found in the Nexus.',
                        visualPromptMod: result.loot.name,
                        cost: 0,
                        icon: 'ri-treasure-map-line'
                    };
                    const updatedProfile = { ...activeProfile!, inventory: [...activeProfile!.inventory, newItem] };
                    onUpdateProfile(updatedProfile);
                    setDroppedItem(newItem);
                    addEchoMessage(AgentName.RPGNexusAgent, `Loot acquired: ${newItem.name}`, 'text-emerald-300');
                }

                // Chance to regen visual if narrative suggests scene change or major event
                if (Math.random() > 0.7 || result.narrative.includes("arrive") || result.narrative.includes("enter")) {
                     generateSceneVisuals(location, result.narrative);
                }

             } catch (jsonErr) {
                 console.error("JSON Parse Error", jsonErr);
                 // Fallback
                 addToLog(response, 'narration');
                 setSceneDescription(response);
             }
          }
      } catch (e) {
          console.error("Action Error", e);
          addEchoMessage(AgentName.System, "Nexus connection interrupted.", "text-rose-400");
      } finally {
          setIsProcessing(false);
      }
  };

  const handleForceVisualRegen = () => {
      if (location && sceneDescription) {
          generateSceneVisuals(location, sceneDescription);
      }
  };

  const handleCompileChronicle = () => {
      const textContent = narrativeLog.map(l => `[${new Date(l.timestamp).toLocaleTimeString()}] ${l.text}`).join('\n\n');
      const blob = new Blob([textContent], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Chronicle_${activeProfile?.name}_${Date.now()}.txt`;
      a.click();
      addEchoMessage(AgentName.RPGNexusAgent, "Chronicle compiled and downloaded.", "text-emerald-300");
  };

  const handleUseItem = (item: MarketItem) => {
      if (!activeProfile) return;
      let used = false;
      let newIntegrity = integrity;
      let newSanity = sanity;

      if (['Consumable', 'Food'].includes(item.type)) {
          newIntegrity = Math.min(100, integrity + 25);
          newSanity = Math.min(100, sanity + 15);
          used = true;
          addEchoMessage(AgentName.RPGNexusAgent, `Consumed ${item.name}. Vitals restored.`, "text-emerald-300");
      } else {
           addEchoMessage(AgentName.RPGNexusAgent, `Cannot use ${item.name} directly.`, "text-yellow-300");
      }

      if (used) {
          setIntegrity(newIntegrity);
          setSanity(newSanity);
          const newInv = activeProfile.inventory.filter(i => i.id !== item.id);
          onUpdateProfile({ ...activeProfile, inventory: newInv });
          setShowInventoryOverlay(false);
      }
  };

  const handleInitializeGame = async () => {
      if (!selectedStartLoc || !selectedQuestTemplate || !activeProfile) return;
      setIsProcessing(true);
      setGameMode('PLAYING');
      setLocation(selectedStartLoc);
      const initialQuest: RPGQuest = {
          id: `quest-${Date.now()}`,
          title: selectedQuestTemplate.title,
          description: selectedQuestTemplate.desc,
          status: 'active',
          progress: 0,
          difficulty: selectedQuestTemplate.difficulty as 'Normal' | 'Hard' | 'Extreme',
          rewards: { xp: 500, flux: 250 }
      };
      setActiveQuests([initialQuest]);
      const startNarrative = `You arrive at ${selectedStartLoc}. Your mission: ${selectedQuestTemplate.title}. The air thrums with potential.`;
      setSceneDescription(startNarrative);
      addToLog(startNarrative, 'narration');
      await generateSceneVisuals(selectedStartLoc, startNarrative);
      setIsProcessing(false);
  };

  if (!activeProfile) {
      return (
        <div className="bg-slate-900/90 border border-slate-700 rounded-xl p-8 flex items-center justify-center h-full text-slate-400" style={{ width: typeof width === 'number' ? `${width}px` : width, height: typeof height === 'number' ? `${height}px` : height }}>
            <p>Please initialize a Seeker Identity in the Profile Weaver to access the Nexus.</p>
        </div>
      );
  }

  const containerClasses = `rpg-nexus-panel bg-slate-950/95 backdrop-blur-xl border border-indigo-500/50 rounded-xl shadow-2xl overflow-hidden flex flex-col my-4 relative transition-all duration-500 
    ${criticalState === 'death' ? 'animate-shake border-red-600/80 shadow-[0_0_50px_rgba(220,38,38,0.5)] grayscale' : ''}
    ${criticalState === 'madness' ? 'animate-pulse border-purple-600/80 shadow-[0_0_50px_rgba(147,51,234,0.5)] filter hue-rotate-15 saturate-200' : ''}
  `;

  return (
    <div className={containerClasses} style={{ width: typeof width === 'number' ? `${width}px` : width, height: typeof height === 'number' ? `${height}px` : height }}>

      {/* SETUP MODE */}
      {gameMode === 'SETUP' && (
          <div className="flex flex-col h-full p-6 animate-fade-in-up">
              <h2 className="text-3xl font-cinzel text-center text-indigo-300 mb-6 tracking-widest">CAMPAIGN INITIALIZATION</h2>
              <div className="flex-grow overflow-y-auto custom-scrollbar space-y-6">
                  {/* Step 1: Location */}
                  <div className="space-y-3">
                      <div className="flex justify-between items-center border-b border-slate-700 pb-2">
                          <h4 className="text-lg font-cinzel text-slate-300">1. Select Insertion Point</h4>
                          <button onClick={generateDynamicLocations} disabled={isGeneratingLocations} className="text-xs px-3 py-1 bg-indigo-600 hover:bg-indigo-500 rounded text-white disabled:bg-slate-700">
                            {isGeneratingLocations ? <><i className="ri-loader-4-line animate-spin mr-1"></i>Scanning Sectors...</> : <><i className="ri-radar-line mr-1"></i>Scan for Anomalies</>}
                          </button>
                      </div>
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                        {Object.entries(generatedLocations).length > 0 ? Object.entries(generatedLocations).map(([loc, data]: [string, any]) => (
                            <button key={loc} onClick={() => handleLocationSelect(loc)} className={`text-left p-3 rounded-lg border transition-all h-full flex flex-col ${selectedStartLoc === loc ? 'bg-indigo-900/40 border-indigo-500 ring-1 ring-indigo-400' : 'bg-slate-800/40 border-slate-700 hover:bg-slate-800/60'}`}>
                                <div className="flex justify-between items-start mb-2"><span className={`font-bold ${data.color} text-sm`}>{loc}</span><i className={`${data.icon} text-lg opacity-50`}></i></div>
                                <p className="text-xs text-slate-400 flex-grow">{data.description}</p>
                                <div className="mt-2 text-[10px] uppercase bg-slate-900 px-2 py-1 rounded text-slate-400 w-fit">{data.risk} Risk</div>
                            </button>
                        )) : !isGeneratingLocations && <div className="col-span-3 text-center text-slate-500 italic">Initiate scan to detect insertion points.</div>}
                      </div>
                  </div>
                  {/* Step 2: Quest */}
                  {selectedStartLoc && (
                      <div className="space-y-3 animate-fade-in-up">
                          <h4 className="text-lg font-cinzel text-slate-300 border-b border-slate-700 pb-2 flex justify-between items-center">2. Select Prime Directive {isGeneratingQuests && <span className="text-xs text-amber-400 font-mono animate-pulse">Calculating...</span>}</h4>
                          <div className="space-y-2">
                              {generatedQuests.map(quest => (
                                  <button key={quest.id} onClick={() => setSelectedQuestTemplate(quest)} className={`w-full text-left p-3 rounded-lg border transition-all ${selectedQuestTemplate?.id === quest.id ? 'bg-amber-900/40 border-amber-500 ring-1 ring-amber-400' : 'bg-slate-800/40 border-slate-700 hover:bg-slate-800/60'}`}>
                                      <div className="flex justify-between items-center mb-1"><span className="font-bold text-amber-200">{quest.title}</span><span className="text-[10px] uppercase bg-slate-900 px-2 py-0.5 rounded text-slate-400">{quest.difficulty}</span></div>
                                      <p className="text-xs text-slate-400">{quest.desc}</p>
                                  </button>
                              ))}
                          </div>
                      </div>
                  )}
              </div>
              <div className="mt-6 flex justify-center">
                  <Button onClick={handleInitializeGame} disabled={!selectedStartLoc || !selectedQuestTemplate || isProcessing} className="w-full max-w-sm py-3 text-lg bg-emerald-600 hover:bg-emerald-500 shadow-lg shadow-emerald-500/20">{isProcessing ? 'Initializing Neural Link...' : 'INITIALIZE LINK'}</Button>
              </div>
          </div>
      )}

      {/* PLAY MODE */}
      {gameMode === 'PLAYING' && (
        <>
            {/* ACHIEVEMENT TOAST */}
            {achievementToast && <div className="absolute top-16 left-1/2 transform -translate-x-1/2 z-50 bg-slate-900 border border-yellow-500 rounded-lg p-3 shadow-2xl flex items-center gap-3 animate-slide-down-fade w-64"><div className="text-3xl text-yellow-400"><i className={achievementToast.icon}></i></div><div><p className="text-[10px] text-yellow-600 font-bold uppercase tracking-wider">Achievement Unlocked</p><p className="text-sm text-yellow-100 font-bold">{achievementToast.name}</p></div></div>}
            {/* LEVEL UP TOAST */}
            {levelUpToast && <div className="absolute top-1/3 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-[150] pointer-events-none animate-bounce-in text-center"><h2 className="text-5xl font-cinzel font-bold text-yellow-300 drop-shadow-[0_0_20px_rgba(253,224,71,0.6)] mb-2">LEVEL UP!</h2><p className="text-2xl font-mono text-white tracking-widest bg-black/60 px-4 py-1 rounded">RANK {levelUpToast} REACHED</p></div>}

            {/* CRITICAL OVERLAY */}
            {criticalState && <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md animate-fade-in-up pointer-events-auto"><div className="text-center"><h1 className={`text-6xl font-cinzel font-bold mb-4 tracking-widest ${criticalState === 'death' ? 'text-red-500 glitch-text' : 'text-purple-500 animate-pulse'}`}>{criticalState === 'death' ? 'SIGNAL LOST' : 'MIND FRACTURED'}</h1><p className="text-slate-300 font-cormorant text-xl italic mb-6">{criticalState === 'death' ? 'Integrity Critical. Initiating Reconstruction...' : 'Reality Coherence Failed. Dissolving to Void...'}</p><div className="flex justify-center"><i className={`text-4xl ${criticalState === 'death' ? 'ri-skull-line text-red-500 animate-spin-slow' : 'ri-eye-off-line text-purple-500 animate-pulse'}`}></i></div></div></div>}

            {/* INVENTORY OVERLAY */}
            {showInventoryOverlay && <div className="absolute bottom-20 right-4 z-[60] bg-slate-900 border border-slate-600 rounded-xl shadow-2xl p-4 w-72 animate-slide-up-fade"><div className="flex justify-between items-center mb-3 border-b border-slate-700 pb-2"><h4 className="text-xs font-bold text-amber-300 uppercase tracking-wider">Inventory Bag</h4><button onClick={() => setShowInventoryOverlay(false)} className="text-slate-400 hover:text-white"><i className="ri-close-line"></i></button></div>{activeProfile.inventory.length === 0 ? <p className="text-xs text-slate-500 italic text-center py-4">Bag empty.</p> : <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto custom-scrollbar">{activeProfile.inventory.map((item, idx) => <button key={idx} onClick={() => handleUseItem(item)} className="aspect-square bg-slate-800 border border-slate-700 rounded hover:border-amber-500 flex items-center justify-center relative group" title={`Use ${item.name}`}><i className={`${item.icon} text-lg text-slate-300`}></i>{['Consumable', 'Food'].includes(item.type) && <div className="absolute top-0 right-0 w-2 h-2 bg-green-500 rounded-full"></div>}</button>)}</div>}<p className="text-[9px] text-slate-500 mt-2 text-center">Click item to Use</p></div>}

            {/* Header */}
            <div className="flex justify-between items-center p-3 bg-slate-900 border-b border-indigo-900/50 shrink-0 relative">
                <div className="flex gap-2"><h3 className="text-lg font-cinzel font-bold text-indigo-300 flex items-center"><i className="ri-gamepad-line mr-2"></i>Nexus Engine</h3><div className="flex gap-2"><button onClick={() => setGameMode('SETUP')} className="px-2 py-0.5 bg-slate-800 hover:bg-slate-700 text-[10px] text-slate-400 rounded border border-slate-700">SYSTEM</button><button onClick={() => setShowChronicle(true)} className="px-2 py-0.5 bg-amber-900/40 hover:bg-amber-800/60 text-[10px] text-amber-400 rounded border border-amber-700/50 flex items-center"><i className="ri-book-open-line mr-1"></i>CHRONICLE</button></div></div>
                <div className="flex items-center gap-3"><button onClick={() => setShowSettings(!showSettings)} className={`text-slate-400 hover:text-white transition-colors ${showSettings ? 'text-indigo-400' : ''}`}><i className="ri-settings-4-line text-lg"></i></button><div className="text-xs font-mono text-slate-400 flex gap-3"><span className="hidden sm:inline"><i className="ri-map-pin-line mr-1"></i>{location}</span><span className="text-amber-400"><i className="ri-copper-coin-line mr-1"></i>{activeProfile.flux}</span><span className="text-emerald-400">LVL {activeProfile.level}</span></div></div>
            </div>

            <div className="flex-grow flex flex-col md:flex-row min-h-0">
                {/* Left: Visuals */}
                <div className="h-[40%] md:h-full md:w-1/2 bg-black relative border-b md:border-b-0 md:border-r border-indigo-900/50 flex flex-col shrink-0">
                    <div className="relative flex-grow overflow-hidden group">
                        {sceneVideoUrl ? <video src={sceneVideoUrl} className="w-full h-full object-cover z-10 relative" controls autoPlay loop onPlay={handlePlayAudio}/> : sceneImageUrl ? <img src={sceneImageUrl} alt="Current Scene" className={`w-full h-full object-cover opacity-90 transition-opacity duration-1000 ${criticalState === 'madness' ? 'animate-pulse blur-sm' : ''} ${criticalState === 'death' ? 'grayscale' : ''}`} /> : <div className="w-full h-full flex items-center justify-center text-indigo-500/30 animate-pulse"><i className="ri-landscape-line text-6xl"></i></div>}
                        <div className="absolute top-2 left-2 flex flex-col gap-1.5 w-36 bg-black/60 p-2 rounded-lg border border-slate-600/60 backdrop-blur-md shadow-lg pointer-events-none z-20"><div className="flex items-center text-[10px] text-red-300 font-mono font-bold"><i className="ri-heart-pulse-line mr-1.5 text-red-400"></i> HP<div className="ml-auto w-20 h-2 bg-slate-800 rounded-full overflow-hidden border border-slate-600/50"><div className={`h-full transition-all duration-300 ${integrity < 30 ? 'bg-red-600 animate-pulse' : 'bg-gradient-to-r from-red-600 to-red-400'}`} style={{width: `${integrity}%`}}></div></div></div><div className="flex items-center text-[10px] text-purple-300 font-mono font-bold"><i className="ri-brain-line mr-1.5 text-purple-400"></i> SAN<div className="ml-auto w-20 h-2 bg-slate-800 rounded-full overflow-hidden border border-slate-600/50"><div className={`h-full transition-all duration-300 ${sanity < 30 ? 'bg-purple-600 animate-pulse' : 'bg-gradient-to-r from-purple-600 to-purple-400'}`} style={{width: `${sanity}%`}}></div></div></div></div>
                        <div className="absolute top-2 right-2 flex flex-col gap-2 z-20"><button onClick={handleForceVisualRegen} disabled={isImageGenerating || !!criticalState} className="p-1.5 bg-black/60 text-slate-300 hover:text-white rounded border border-slate-600 hover:border-slate-400 transition-opacity opacity-0 group-hover:opacity-100 disabled:opacity-0"><i className={`ri-camera-lens-line ${isImageGenerating ? 'animate-spin' : ''}`}></i></button><button onClick={handleGenerateVideo} disabled={isVideoGenerating || !sceneImageUrl || !!criticalState} className={`p-1.5 bg-black/60 text-slate-300 hover:text-fuchsia-300 rounded border border-slate-600 hover:border-fuchsia-500 transition-opacity opacity-0 group-hover:opacity-100 ${isVideoGenerating ? 'opacity-100' : ''} disabled:opacity-0`}><i className={`ri-movie-2-line ${isVideoGenerating ? 'animate-pulse text-fuchsia-400' : ''}`}></i></button></div>
                        {droppedItem && <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-slate-900/95 border border-amber-500/50 rounded-lg p-3 shadow-2xl flex flex-col items-center gap-2 animate-bounce-in z-50 min-w-[200px]"><div className="text-3xl text-amber-400"><i className={droppedItem.icon}></i></div><div className="text-center"><p className="text-sm text-amber-100 font-bold">{droppedItem.name}</p><p className="text-[10px] text-slate-400 uppercase">{droppedItem.rarity} {droppedItem.type}</p></div><button onClick={() => setDroppedItem(null)} className="text-[10px] text-slate-500 hover:text-slate-300 underline">Dismiss</button></div>}
                        {droppedCard && <div className="absolute top-1/3 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-gradient-to-br from-indigo-900 to-purple-900 border-2 border-fuchsia-400 rounded-xl p-4 shadow-[0_0_30px_rgba(232,121,249,0.5)] flex flex-col items-center gap-3 animate-zoom-in z-[60] min-w-[220px] aspect-[2.5/3.5]"><div className="absolute -top-3 bg-fuchsia-600 text-white text-[10px] font-bold px-3 py-0.5 rounded-full uppercase tracking-wider shadow-lg">Card Captured</div><div className="w-full h-24 bg-black/50 rounded border border-white/20 flex items-center justify-center mb-1"><i className={`${droppedCard.icon} text-5xl text-fuchsia-300 drop-shadow-md`}></i></div><div className="text-center w-full"><p className="text-lg font-cinzel font-bold text-white leading-tight">{droppedCard.name}</p><p className="text-[9px] text-fuchsia-200 uppercase tracking-widest mt-1 border-t border-fuchsia-500/50 pt-1">{droppedCard.type} • {droppedCard.rarity}</p></div><p className="text-[9px] text-slate-300 italic text-center leading-snug px-1 line-clamp-3">{droppedCard.description}</p><button onClick={() => setDroppedCard(null)} className="mt-auto w-full py-1.5 bg-fuchsia-700 hover:bg-fuchsia-600 text-white text-xs font-bold rounded shadow-md transition-colors">Collect</button></div>}
                        <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black via-black/80 to-transparent p-4 pt-12 pointer-events-none"><p className="text-sm font-cormorant text-slate-200 italic leading-relaxed text-shadow-sm">"{sceneDescription}"</p></div>
                        {(isProcessing || isImageGenerating || isVideoGenerating) && !criticalState && <div className="absolute inset-0 bg-black/60 flex items-center justify-center backdrop-blur-sm z-10 transition-opacity duration-300 pointer-events-none"><div className="text-indigo-400 font-cinzel animate-pulse flex flex-col items-center"><i className="ri-loader-4-line text-3xl mb-2 animate-spin"></i>{isProcessing ? 'Weaving Fate...' : (isVideoGenerating ? 'Manifesting Motion...' : 'Painting Reality...')}</div></div>}
