// Standard Actions
const STANDARD_ACTIONS: RPGAction[] = [
  { id: 'explore', label: 'Explore', type: 'explore', risk: 20, prompt: 'Explore the immediate surroundings.', color: 'text-emerald-400 border-emerald-500/30 icon-emerald-400' },
  { id: 'scan', label: 'Scan', type: 'explore', risk: 10, prompt: 'Scan for resonant signatures and hidden glyphs.', color: 'text-sky-400 border-sky-500/30 icon-sky-400' },
  { id: 'commune', label: 'Commune', type: 'talk', risk: 30, prompt: 'Attempt to commune with local entities or echoes.', color: 'text-purple-400 border-purple-500/30 icon-purple-400' },
  { id: 'ritual', label: 'Ritual', type: 'ritual', risk: 50, prompt: 'Perform a minor stabilization ritual.', color: 'text-amber-400 border-amber-500/30 icon-amber-400' },
