        case 'trade': return 'ri-exchange-dollar-line';
        default: return 'ri-question-line';
    }
}

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  width,
  height,
  addEchoMessage,
  activeProfile,
  onUpdateProfile,
  currentEntropy,
  systemMode,
  onArtifactCreated,
  artifacts,
  savedState,
  onSaveState,
  onUpdateSystemMetrics
}) => {
  const { invokeGemini, isGenerating } = useGemini();
  const scrollRef = useRef<HTMLDivElement>(null);

  // --- Local State ---
  // If savedState is provided, use it, otherwise initialize defaults
  const [narrativeLog, setNarrativeLog] = useState<{ text: string; type: 'narration' | 'action' | 'system' | 'ambient'; timestamp: number }[]>(
    savedState?.narrativeHistory || [{ text: "The Nexus Interface initializes. You stand at the precipice of the Void.", type: 'system', timestamp: Date.now() }]
  );

  const [currentLocation, setCurrentLocation] = useState<string>(savedState?.currentLocation || "The Void Edge");
  const [availableActions, setAvailableActions] = useState<RPGDynamicAction[]>(savedState?.availableActions || []);
  const [customAction, setCustomAction] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const [showInventoryOverlay, setShowInventoryOverlay] = useState(false);

  // Vitals could be part of profile or RPG state. Assuming RPG state for now as per types.
  const [vitals, setVitals] = useState<{ integrity: number, sanity: number }>(savedState?.vitals || { integrity: 100, sanity: 100 });

  // Sync back to parent state whenever RPG state changes
  useEffect(() => {
    if (onSaveState) {
      onSaveState({
        currentLocation: currentLocation as any,
        narrativeHistory: narrativeLog,
        activeQuests: savedState?.activeQuests || [], // Persist existing if not modified locally yet
        lastActionTimestamp: Date.now(),
        vitals,
        availableActions
      });
    }
  }, [narrativeLog, currentLocation, vitals, availableActions, onSaveState]); 

  // Auto-scroll
  useEffect(() => {
    if (scrollRef.current) {
        scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [narrativeLog]);

  const criticalState = vitals.integrity <= 0 || vitals.sanity <= 0;

  const handleAction = async (actionText: string, type: 'action' | 'system' = 'action', risk: number = 0) => {
    if (isProcessing || criticalState) return;
    if (!activeProfile) {
        addEchoMessage(AgentName.RPGNexusAgent, "No active Seeker Profile found. Please initialize in Profile Weaver.", "text-rose-400");
        return;
    }

    setIsProcessing(true);
    setCustomAction(""); // Clear input

    // Optimistic Update
    const newLogEntry = { text: actionText, type: type as any, timestamp: Date.now() };
    setNarrativeLog(prev => [...prev, newLogEntry]);

    try {
        const systemPrompt = `You are the Dungeon Master (Nexus Engine) for a text-based RPG set in the Tri-Sophian Codex universe. 
        Current Seeker: ${activeProfile.name} (${activeProfile.race} ${activeProfile.class}).
        Traits: ${activeProfile.selfTraits.join(', ')}.
        Current Location: ${currentLocation}.
        System Entropy: ${currentEntropy.toFixed(2)}.
        System Mode: ${systemMode}.
        Current Vitals: Integrity ${vitals.integrity}%, Sanity ${vitals.sanity}%.

        The user performs the action: "${actionText}" (Risk: ${risk}%).

        Generate the outcome. 
        1. Narrative description (max 3 sentences).
        2. Identify if any vitals change (integrity damage, sanity loss/gain).
        3. Identify if any loot is found (rarely).
        4. Suggest 2-3 dynamic follow-up actions.
        5. If risk was high and entropy is high, consequences should be severe.

        Output format (JSON):
        {
            "narrative": "string",
            "vitalsDelta": {"integrity": number, "sanity": number},
            "entropyDelta": number, 
            "newLocation": "string (optional)",
            "dynamicActions": [{"label": "string", "type": "explore|talk|combat|ritual", "risk": number}],
            "loot": {"name": "string", "type": "string", "rarity": "string", "desc": "string"} (optional)
        }`;

        const response = await invokeGemini(systemPrompt, "You are the Nexus Engine."); 

        if (response) {
            // Attempt to parse JSON. Gemini might wrap in markdown code blocks.
            const jsonMatch = response.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                const result = JSON.parse(jsonMatch[0]);

                // Update Narrative
                setNarrativeLog(prev => [...prev, { text: result.narrative, type: 'narration', timestamp: Date.now() }]);

                // Update Vitals
                if (result.vitalsDelta) {
                    setVitals(prev => ({
                        integrity: Math.min(100, Math.max(0, prev.integrity + (result.vitalsDelta.integrity || 0))),
                        sanity: Math.min(100, Math.max(0, prev.sanity + (result.vitalsDelta.sanity || 0)))
                    }));
                    if (result.vitalsDelta.integrity < 0 || result.vitalsDelta.sanity < 0) {
                        addEchoMessage(AgentName.RPGNexusAgent, `Vitals impacted: Int ${result.vitalsDelta.integrity || 0}, San ${result.vitalsDelta.sanity || 0}`, "text-rose-400");
                    }
                }

                // Update System Entropy/Negentropy via parent callback
                if (result.entropyDelta && onUpdateSystemMetrics) {
                     onUpdateSystemMetrics(result.entropyDelta, -result.entropyDelta); // Simple inverse for negentropy
                }

                // Update Location
                if (result.newLocation) {
                    setCurrentLocation(result.newLocation);
                    setNarrativeLog(prev => [...prev, { text: `Moved to: ${result.newLocation}`, type: 'system', timestamp: Date.now() }]);
                }

                // Update Actions
                if (result.dynamicActions) {
                    setAvailableActions(result.dynamicActions.map((a: any) => ({...a, id: `dyn-${Date.now()}-${Math.random()}`, isDynamic: true})));
                }

                // Handle Loot
                if (result.loot && onArtifactCreated) {
                     const newArtifact: CodexArtifact = {
                        id: `loot-${Date.now()}`,
                        name: result.loot.name,
                        type: ArtifactType.RitualResidue, // Fallback type
                        rarity: result.loot.rarity as ArtifactRarity || ArtifactRarity.Common,
                        description: result.loot.desc,
                        timestamp: Date.now()
                     };
                     onArtifactCreated(newArtifact);
                     setNarrativeLog(prev => [...prev, { text: `Acquired: ${result.loot.name} (${result.loot.rarity})`, type: 'system', timestamp: Date.now() }]);
                }

            } else {
                 // Fallback if JSON parse fails
                 setNarrativeLog(prev => [...prev, { text: response, type: 'narration', timestamp: Date.now() }]);
            }
        } else {
            setNarrativeLog(prev => [...prev, { text: "The Nexus is silent. (API Error)", type: 'system', timestamp: Date.now() }]);
        }

    } catch (e) {
        console.error("RPG Action Error:", e);
        setNarrativeLog(prev => [...prev, { text: "Connection to Nexus Engine severed.", type: 'system', timestamp: Date.now() }]);
    } finally {
        setIsProcessing(false);
    }
  };

