                              if (entry.isVideo) return <div key={idx} className="my-8 text-center bg-black/40 p-4 rounded-lg border border-amber-900/30"><video src={entry.mediaUrl} controls className="max-w-full max-h-[300px] mx-auto rounded border border-slate-700 shadow-lg" /><p className="text-sm italic text-slate-400 mt-2">{entry.text}</p></div>;
                              if (entry.type === 'action') return <p key={idx} className="font-bold text-amber-200 mt-4 mb-2 pl-4 border-l-2 border-amber-600">› {entry.text}</p>;
                              if (entry.type === 'system') return <p key={idx} className="font-mono text-xs text-slate-500 bg-slate-900/50 p-1 pl-2 border-l border-slate-700">{entry.text}</p>;
