// Initialize Singletons
const soundEngine = new SoundEngine();
const voiceEngine = new VoiceEngine();

const App: React.FC = () => {
  // -- Global State --
  const [isBooting, setIsBooting] = useState(true);
  const [currentModuleId, setCurrentModuleId] = useState<string>('rpg_nexus');

  const [activeProfile, setActiveProfile] = useState<SeekerProfile | null>(null);
  const [currentEntropy, setCurrentEntropy] = useState<number>(0.25); // Base Entropy
  const [effectiveSystemEntropy, setEffectiveSystemEntropy] = useState<number>(0.25); // After overrides
  const [negentropyLevel, setNegentropyLevel] = useState<number>(0.75);
  const [lambdaValue, setLambdaValue] = useState<number>(1.0);
  const [currentPhase, setCurrentPhase] = useState<string>("Phase 9.5: Emerald Codex");
  const [currentCodexModeId, setCurrentCodexModeId] = useState<CodexModeId>(CodexModeId.SYMBIOTIC_WEAVE);

  const [echoLog, setEchoLog] = useState<any[]>([]);
  const [artifacts, setArtifacts] = useState<CodexArtifact[]>([]);
  const [eventHistory, setEventHistory] = useState<HistoricalEvent[]>([]);
  const [rpgState, setRpgState] = useState<RPGGameState | undefined>(undefined);

  // -- UI Toggles --
  const [showSaveLoadModal, setShowSaveLoadModal] = useState(false);
  const [showOracleModal, setShowOracleModal] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [showSigilOverlay, setShowSigilOverlay] = useState(false);
  const [isBugaModeActive, setIsBugaModeActive] = useState(false);

  const { invokeGemini, isGenerating: isGeminiGenerating } = useGemini();

  // -- Helpers --
  const addEchoMessage = (source: string, text: string, colorClass: string = 'text-slate-300', isAutoEcho: boolean = false, meta?: any) => {
    const newMessage = {
      id: `echo-${Date.now()}-${Math.random()}`,
      source,
      text,
      colorClass,
      timestamp: new Date().toISOString(),
      ...meta
    };
    setEchoLog(prev => [newMessage, ...prev].slice(0, 100)); // Keep last 100

    if (meta?.eventType) {
        setEventHistory(prev => [...prev, { timestamp: Date.now(), type: meta.eventType, data: meta.eventData }]);
    }
  };

  // -- Systems --
  const { 
    interpretations: dreambloomInterpretations, 
    isAutoActive: isDreambloomAuto, 
    toggleAuto: toggleDreambloomAuto, 
    conjurePulse: conjureDreambloom,
    isLoading: isDreambloomLoading
  } = useDreambloomSystem(addEchoMessage);

  const { temporalWhispers, playAudio: playTemporalAudio } = useTemporalWhispers(eventHistory, () => {});

  const { activeWhispers, dismissWhisper } = useWhisperSystem({
      entropy: effectiveSystemEntropy,
      activeTraits: activeProfile?.selfTraits || [],
      playbackStatus: 'playing',
      activeGlyph: null
  });

  const { saveGame, loadGame, getSaveSlots, saveStatus, lastSavedTime } = useCodexPersistence(
    ['ActiveProfile', 'RPGState', 'Artifacts', 'EventHistory'], 
    { activeProfile, rpgState, artifacts, eventHistory }
  );

  // -- Effects --
  useEffect(() => {
    // Simple entropy fluctuation simulation
    const interval = setInterval(() => {
        const fluctuation = (Math.random() - 0.5) * 0.01;
        const newEntropy = Math.max(0, Math.min(1, currentEntropy + fluctuation));
        setCurrentEntropy(newEntropy);
        // Effective entropy might be overridden by modes in a real scenario, here we sync
        setEffectiveSystemEntropy(newEntropy);
        soundEngine.updateDrone(newEntropy);
    }, 2000);
    return () => clearInterval(interval);
  }, [currentEntropy]);

  useEffect(() => {
      soundEngine.initializeDrone();
  }, []);

  const handleToggleMute = () => {
      const newMuted = !isMuted;
      setIsMuted(newMuted);
      soundEngine.toggleMute(newMuted);
  };

  const handleLaunchModule = (moduleId: string) => {
      setCurrentModuleId(moduleId);
      addEchoMessage(AgentName.System, `Interface switched to module: ${moduleId.toUpperCase()}`, 'text-cyan-300');
      soundEngine.playSFX('click');
  };

  // -- Module Rendering Logic --
  const renderCenterModule = () => {
