        case 'flux_farm':
            return <FluxFarmPanel {...commonProps} height={600} activeProfile={activeProfile} onUpdateProfile={setActiveProfile} currentEntropy={effectiveSystemEntropy} addEchoMessage={addEchoMessage} />;
        case 'dreambloom':
            return <CodexDreamPanel {...commonProps} height={700} currentEntropy={effectiveSystemEntropy} currentAxioms={[]} lambdaValue={lambdaValue} negentropyLevel={negentropyLevel} echoLog={echoLog} addEchoMessage={addEchoMessage} currentPhase={currentPhase} chaliceStatus="Stable" onArtifactCreated={(a) => setArtifacts(prev => [...prev, a])} onLaunchDreambloom={() => conjureDreambloom()} />;
        case 'mutation_loom':
            return <MutationLoomPanel glyphMutationNodes={[]} onWeaveGlyphs={async () => undefined} mutationLoomState={{glyph1Id:null, glyph2Id:null, entropyInjection:0, traitFocus:[], isWeaving:false}} setMutationLoomState={() => {}} addEchoMessage={addEchoMessage} isGeminiGenerating={isGeminiGenerating} />;
        case 'glyph_composer':
            return <GlyphComposerPanel {...commonProps} addEchoMessage={addEchoMessage} isBugaModeActive={isBugaModeActive} />;
        case 'emerald_tablet':
            return <EmeraldTabletDecryptionPanel {...commonProps} height={600} currentSystemEntropy={effectiveSystemEntropy} currentEleganceIndex={0.95} addEchoMessage={addEchoMessage} />;
        case 'celestial_anomaly':
            return <CelestialAnomalyWeaverPanel {...commonProps} height={500} addEchoMessage={addEchoMessage} />;
        case 'crystal_garden':
            return <CrystalFormationPanel {...commonProps} height={500} currentEntropy={effectiveSystemEntropy} />;
        case 'geometry_explorer':
            return <CosmicEntropyGeometryGenerator {...commonProps} height={550} currentEntropy={effectiveSystemEntropy} currentPhase={currentPhase} chaliceStatus="Stable" currentGeoMode="GlyphDNA" onSetGeoMode={() => {}} />;
        case 'exotic_mechanisms':
            return <ExoticMechanismsPanel {...commonProps} height={500} currentEntropy={effectiveSystemEntropy} addEchoMessage={addEchoMessage} />;
        case 'celestial_entropy':
            return <CelestialEntropyCyclePanel {...commonProps} height={500} currentEntropy={effectiveSystemEntropy} />;
        case 'dimension_diagram':
            return <EntropyDimensionDiagramPanel {...commonProps} height={500} currentEntropy={effectiveSystemEntropy} isFractalModeEnabled={true} />;
        case 'glyph_vis':
            return <VisualizationMatrixPanel {...commonProps} height={600} />;
        case 'crm_dashboard':
            return <CosmicResonanceDashboardPanel {...commonProps} height={500} addEchoMessage={addEchoMessage} />;
        case 'temporal_ops':
            return <TemporalOperationsConsolePanel {...commonProps} height={600} addEchoMessage={addEchoMessage} />;
        case 'drift_differential':
            return <DriftDifferentialOverlay currentEntropy={effectiveSystemEntropy} glyphDriftHistory={[]} glyphMutationNodes={[]} currentRitualContext="Standard" isGeminiGenerating={isGeminiGenerating} addEchoMessage={addEchoMessage} logGeminiNarrativeDriftEvent={() => {}} />;
        case 'harmonic_core':
            return <HarmonicCorePanel lambdaValue={lambdaValue} status="Stabilized" eleganceIndex={0.98} />;
        case 'entropy_diagnostics':
            return <EntropyDiagnosticsPanel baseEntropy={currentEntropy} effectiveEntropy={effectiveSystemEntropy} masterEntropyOverridePercent={0} entropyHistory={[currentEntropy]} playbackTime={0} isPlaying={true} />;
        case 'peptide_sim':
            return <PeptideSimulationPanel {...commonProps} height={600} addEchoMessage={addEchoMessage} />;
        case 'codex_pandium':
            return <CodexPandiumPanel {...commonProps} height={600} />;
        case 'datachega':
            return <DatachegaResthetPanel addEchoMessage={addEchoMessage} />;
        case 'aethel_update':
            return <AethelWeftCodexUpdatePanel />;
        case 'chronicle_display':
            return <ChronicleReliquaryPanel {...commonProps} height={600} artifacts={artifacts} addEchoMessage={addEchoMessage} />;
        case 'phoenix_tablet':
            return <TabletOfThePhoenixPanel />;
        case 'shatterpoint_trace':
            return <ShatterpointTracePanel objective="Trace Origin" triggerGlyph="Unknown" axiomaticLinks={[]} traceParameters={{}} oracleCommentary="Searching..." />;
        case 'buga_codex':
            return <BugaGlyphCodexPanel width={600} height={500} />;
        case 'flora_chamber':
            return <BloodInkFloraChamber activeSpeciesName={null} allSpeciesData={{}} />;
        case 'sigil_bloom':
            return <SigilBloomVariantPanel glyphMutationNodes={[]} onRevealBloomVariants={() => {}} sigilBloomVariants={[]} selectedBloomVariantId={null} onSelectBloomVariant={() => {}} isGeneratingBloomVariants={false} isGeminiBusy={isGeminiGenerating} />;
        case 'agent_directory':
             return <div className="p-4 text-center text-slate-500">Agent Directory Offline</div>;
        default:
            return <RPGNexusPanel {...commonProps} height={650} addEchoMessage={addEchoMessage} activeProfile={activeProfile} onUpdateProfile={setActiveProfile} currentEntropy={effectiveSystemEntropy} onArtifactCreated={(a) => setArtifacts(prev => [...prev, a])} savedState={rpgState} onSaveState={setRpgState} artifacts={artifacts} />;
      }
  };

  // -- Boot Sequence --
  if (isBooting) {
    return <BootSequence onComplete={() => setIsBooting(false)} />;
  }

  // -- Main Layout --
  return (
    <SystemStateProvider value={{ entropy: effectiveSystemEntropy, activeTraits: activeProfile?.selfTraits || [], playbackStatus: 'playing', activeGlyph: null, negentropyLevel, isNegentropyStable: true }}>
        <div className="app-container flex flex-col h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
            <Header 
                currentEntropy={effectiveSystemEntropy}
                negentropy={negentropyLevel}
                lambda={lambdaValue}
                isMuted={isMuted}
                onToggleMute={handleToggleMute}
                onLaunchNexus={() => handleLaunchModule('rpg_nexus')}
                onOpenSaveLoadModal={() => setShowSaveLoadModal(true)}
                onExportSave={async () => {/* Implement export */}}
                onImportSave={async (f) => {/* Implement import */}}
                saveStatus={saveStatus}
                lastSavedTime={lastSavedTime}
                // ... Wire up other Header props as needed with dummy functions or real handlers
                onProvokeThornedRose={() => {}}
                onTuneFrequency={() => {}}
                onRecallAncestor={() => {}}
                onBurnPetals={() => {}}
                onAwakenLotusDream={() => {}}
                onPulseAstralJasmine={() => {}}
                onGraftThorns={() => {}}
                onToggleAutoEcho={() => {}}
                onAmplifyVoices={() => {}}
                onSeedDream={() => {}}
                isAutoEchoPaused={false}
                onInvokeGeminiOracle={() => setShowOracleModal(true)}
                onContextualOracleQuery={() => setShowOracleModal(true)}
                onToggleAshfall={() => {}}
                showAshfall={false}
                showLogicWebDebug={false}
                onToggleLogicWebDebug={() => {}}
                isAuditing={false}
                onToggleAuditMode={() => {}}
                isAuditModeLocked={false}
                currentCodexModeId={currentCodexModeId}
                activateCodexMode={setCurrentCodexModeId}
                onDumpThreadSummary={() => {}}
                showSigilOverlay={showSigilOverlay}
                onToggleSigilOverlay={() => setShowSigilOverlay(!showSigilOverlay)}
                onTraceThreadcoil={() => {}}
                onReEnterJunction={() => {}}
                onExtractSigil={() => {}}
                isBugaModeActive={isBugaModeActive}
                onToggleBugaMode={() => setIsBugaModeActive(!isBugaModeActive)}
            />

            <div className="flex flex-grow overflow-hidden relative">

                {/* Left Column: Status & Identity */}
                <aside className="w-[320px] flex-shrink-0 flex flex-col gap-4 p-4 overflow-y-auto custom-scrollbar border-r border-slate-800 bg-slate-900/40">
                    <SeekerProfileWeaverPanel 
                        width="100%" 
                        height="auto"
                        addEchoMessage={addEchoMessage}
                        onProfileCreated={setActiveProfile}
                        existingProfile={activeProfile}
                        onUpdateProfile={setActiveProfile}
                    />
                    <SeekerVitalsPanel 
                        activeProfile={activeProfile}
                        rpgState={rpgState}
                    />
                     <SeekerAuraDisplay 
                        seekerTraits={activeProfile?.selfTraits || []}
                        currentEntropy={effectiveSystemEntropy}
                        dominantAgentTone={null}
                        lastRitualOutcome={null}
                        width={280}
                        height={280}
                        auraColor={activeProfile?.auraColor}
                    />
                    <ChronicleReliquaryPanel 
                        width="100%" 
                        height={400} 
                        artifacts={artifacts} 
                        addEchoMessage={addEchoMessage} 
                    />
                </aside>

                {/* Center Column: Main Stage */}
                <main className="flex-grow flex flex-col relative overflow-hidden bg-slate-950/50">
                    <div className="flex-grow overflow-y-auto custom-scrollbar p-4 flex flex-col items-center">
                        {renderCenterModule()}
                        <SystemModulesPanel onLaunchModule={handleLaunchModule} width="90%" />
                    </div>
                </main>

                {/* Right Column: Operations & Logs */}
                <aside className="w-[340px] flex-shrink-0 flex flex-col gap-4 p-4 overflow-y-auto custom-scrollbar border-l border-slate-800 bg-slate-900/40">
                     <HarmonicCorePanel lambdaValue={lambdaValue} status="Stabilized" eleganceIndex={0.98} />
                     <EntropyDiagnosticsPanel 
                        baseEntropy={currentEntropy} 
                        effectiveEntropy={effectiveSystemEntropy} 
                        masterEntropyOverridePercent={0} 
                        entropyHistory={[currentEntropy]} 
                        playbackTime={0} 
                        isPlaying={true} 
                     />
                     <TemporalOperationsConsolePanel width="100%" height={500} addEchoMessage={addEchoMessage} />
                     <TemporalResonanceLogPanel width="100%" height={400} />
                </aside>

            </div>

            <Footer />

            {/* Overlays */}
            <WhisperOverlay 
                activeWhispers={activeWhispers} 
                onDismiss={dismissWhisper} 
                voiceEngine={voiceEngine} 
                voiceProfiles={voiceProfiles} 
            />
            <SaveLoadModal 
                isOpen={showSaveLoadModal} 
                onClose={() => setShowSaveLoadModal(false)} 
                onSave={saveGame} 
                onLoad={async (slot) => { const s = await loadGame(slot); if(s) { setActiveProfile(s.activeProfile || null); setRpgState(s.rpgState); setArtifacts(s.artifacts || []); setEventHistory(s.eventHistory || []); } }} 
                fetchSlots={getSaveSlots} 
            />
            <OracleSanctumModal 
                isOpen={showOracleModal} 
                onClose={() => setShowOracleModal(false)} 
                currentEntropy={effectiveSystemEntropy} 
                currentMode={currentModuleId} 
                addEchoMessage={addEchoMessage} 
            />
        </div>
    </SystemStateProvider>
  );
};

